Q='SELECT ?item ?itemLabel ?coord WHERE {
  ?item wdt:P31 wd:Q39715; wdt:P17 wd:Q142; wdt:P625 ?coord.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} LIMIT 20'
curl -sG https://query.wikidata.org/sparql -H 'Accept: application/json' \
  -H 'User-Agent: my-project/1.0 (you@example.com)' --data-urlencode "query=$Q" | python3 -m json.tool | head -30
